<?php
/** Fixed-target metadata exporter. No database writes and no row contents. */
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__).'/backend/src/autoload.php';
require __DIR__.'/donation_consolidation_support.php';
$o=getopt('',['target:']);$name=$o['target']??'bloodmatch_test';
try{
    $p=consolidationTarget(match($name){'bloodmatch_test'=>'test','bloodmatch'=>'application',default=>throw new LogicException('Unsupported fixed target.')});
    $test=$name==='bloodmatch_test';$suffix=$test?'':'_application';$root=dirname(__DIR__).'/docs/';
    $tables=$p->query("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' ORDER BY TABLE_NAME")->fetchAll(PDO::FETCH_COLUMN);
    $columns=$p->query('SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE,COLUMN_TYPE,IS_NULLABLE,EXTRA,GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME,ORDINAL_POSITION')->fetchAll();
    $indexes=$p->query('SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() GROUP BY TABLE_NAME,INDEX_NAME,NON_UNIQUE ORDER BY TABLE_NAME,INDEX_NAME')->fetchAll();
    $fks=$p->query('SELECT k.TABLE_NAME,k.CONSTRAINT_NAME,k.COLUMN_NAME,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,k.ORDINAL_POSITION,r.DELETE_RULE,r.UPDATE_RULE FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME AND r.TABLE_NAME=k.TABLE_NAME WHERE k.TABLE_SCHEMA=DATABASE() ORDER BY k.TABLE_NAME,k.CONSTRAINT_NAME,k.ORDINAL_POSITION')->fetchAll();
    $checks=$p->query('SELECT TABLE_NAME,CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() ORDER BY TABLE_NAME,CONSTRAINT_NAME')->fetchAll();
    $s=$p->prepare('SELECT 1 FROM schema_migrations WHERE name=?');$s->execute(['032_consolidate_donation_storage.sql']);$new=(bool)$s->fetchColumn();
    $schema=[];foreach($columns as $c)$schema[$c['TABLE_NAME']][]=$c;
    $grouped=[];foreach($fks as $fk)$grouped[$fk['TABLE_NAME'].':'.$fk['CONSTRAINT_NAME']][]=$fk;
    $stamp=(new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')))->format('Y-m-d H:i').' Asia/Manila';
    $status=$test?'TESTED DISPOSABLE SCHEMA - application rollout pending':'APPLICATION SCHEMA - migration 032 '.($new?'recorded':'NOT applied');
    $intro="Generated from **$name:3306**, $stamp. **$status**. ".count($tables)." physical base tables.\n\n";
    $intro.=$new?"The active design uses six donation tables. `donation_credits`, `donation_report_holds`, and `compatibility_matrix` remain as cutover source snapshots, not current writers. After separately approved retirement: 35 active base tables, including `compatibility_pairs`.\n\n":"This is the actual application model, with separate donation credit/hold tables and the original compatibility list. It must not be presented as the tested consolidated schema.\n\n";
    $intro.="See [rollout and test checkpoint](DONATION_CONSOLIDATION_032.md), [data dictionary](data_dictionary$suffix.md), and [SVG](erd$suffix.svg). PK = primary key; FK = enforced reference; UK is shown on a column only for single-column uniqueness. Composite keys are listed in the dictionary.\n\n";
    $md="# BloodMatch ERD\n\n$intro```mermaid\nerDiagram\n";
    foreach($grouped as $parts){$f=$parts[0];$child=$f['TABLE_NAME'];$fkCols=array_column($parts,'COLUMN_NAME');$optional=false;foreach($schema[$child] as $c)if(in_array($c['COLUMN_NAME'],$fkCols,true)&&$c['IS_NULLABLE']==='YES')$optional=true;
        $one=false;foreach($indexes as $i)if($i['TABLE_NAME']===$child&&(int)$i['NON_UNIQUE']===0&&array_diff(explode(',',$i['cols']),$fkCols)===[])$one=true;
        $md.='    '.$f['REFERENCED_TABLE_NAME'].' '.($optional?'|o':'||').'--'.($one?'o|':'o{').' '.$child.' : "'.implode(', ',$fkCols).'"'."\n";
    }
    foreach($schema as $table=>$cols){$md.="    $table {\n";foreach($cols as $c){$flags=[];foreach($indexes as $i)if($i['TABLE_NAME']===$table){if($i['INDEX_NAME']==='PRIMARY'&&in_array($c['COLUMN_NAME'],explode(',',$i['cols']),true))$flags[]='PK';elseif((int)$i['NON_UNIQUE']===0&&$i['cols']===$c['COLUMN_NAME'])$flags[]='UK';}foreach($fks as $f)if($f['TABLE_NAME']===$table&&$f['COLUMN_NAME']===$c['COLUMN_NAME']){$flags[]='FK';break;}$flags=array_unique($flags);$note=($c['IS_NULLABLE']==='YES'?'nullable; ':'').$c['EXTRA'];$md.='        '.strtoupper($c['DATA_TYPE']).' '.$c['COLUMN_NAME'].($flags?' '.implode(',',$flags):'').($note!==''?' "'.trim($note,'; ').'"':'')."\n";}$md.="    }\n";}
    $md.="```\n\nOptionality is read from nullable FKs; maximum child cardinality is inferred from actual unique keys. The tested 032 design adds a composite donor/match FK and context identity triggers; 033 makes accepted context identity immutable. These guarantees apply only to targets with the respective migration markers. Context deletion continues using SET NULL.\n\nLogical references without FKs: audit/notification polymorphic targets; donor reservation donor accounting references; chat report conversation/message snapshots; participant read watermark; preserved actor references. Disconnected infrastructure tables (throttles, settings, migration ledger, pending registrations, compatibility reference) intentionally have no user ownership FK.\n";
    file_put_contents($root.'erd'.$suffix.'.md',$md);
    $dict="# BloodMatch data dictionary\n\n$intro";
    $dict.="Current writers: completion service owns report/credit/hold transitions; proof service owns evidence; workflow repository appends report events; offer service owns accepted contexts and coordination events; correction service owns completed-record review requests. Restrictions remain a monotonic user anchor; fulfillment counts completed matches. Legacy confirmed reports may have no credit or occurrence.\n\n";
    foreach($schema as $table=>$cols){$dict.="## $table\n\n";if($new&&in_array($table,['donation_credits','donation_report_holds','compatibility_matrix'],true))$dict.="**Retained source snapshot. Not authoritative after 032. Retirement requires separate approval.**\n\n";
        $dict.="| Column | Type | Nullable | Generated / extra |\n|---|---|---|---|\n";
        foreach($cols as $c){$extra=$c['EXTRA'].($c['GENERATION_EXPRESSION']?' = '.$c['GENERATION_EXPRESSION']:'');$dict.='| `'.$c['COLUMN_NAME'].'` | `'.$c['COLUMN_TYPE'].'` | '.$c['IS_NULLABLE'].' | '.str_replace('|','\\|',$extra)." |\n";}
        $dict.="\nIndexes / uniqueness:\n\n";foreach($indexes as $i)if($i['TABLE_NAME']===$table)$dict.='- `'.$i['INDEX_NAME'].'` '.((int)$i['NON_UNIQUE']===0?'UNIQUE ':'INDEX ').'(`'.str_replace(',','`, `',$i['cols'])."`)\n";
        foreach($grouped as $parts)if($parts[0]['TABLE_NAME']===$table){$f=$parts[0];$dict.='- FK `'.$f['CONSTRAINT_NAME'].'`: ('.implode(', ',array_column($parts,'COLUMN_NAME')).') references `'.$f['REFERENCED_TABLE_NAME'].'` ('.implode(', ',array_column($parts,'REFERENCED_COLUMN_NAME')).'); DELETE '.$f['DELETE_RULE'].'; UPDATE '.$f['UPDATE_RULE']."\n";}
        foreach($checks as $c)if($c['TABLE_NAME']===$table)$dict.='- CHECK `'.$c['CONSTRAINT_NAME'].'`: `'.str_replace('|','\\|',$c['CHECK_CLAUSE'])."`\n";
        $dict.="\n";
    }
    $dict.="## Consolidated report field meanings (032 targets only)\n\n- `credit_recorded_at`: actual original credit recorded time, or NULL for uncredited claims/legacy confirmations. Independent of status.\n- `credited_donor_id`, `credited_occurred_at`: generated nullable uniqueness keys; NULL for uncredited records.\n- `hold_started_at`: original report hold start; NULL means no hold record existed.\n- `hold_released_at`, `hold_released_by`, `hold_release_basis`, `hold_release_type`: independent release decision. Rejection alone never clears a hold. Reopening clears release fields while preserving the start; events preserve prior release history.\n- Compatibility preference order preserves the former comma-list position exactly; it does not invent a new matching rule.\n\nOne report per match is enforced after 032. Correction requests are review cases, not automatic credit reversals. Multiple photo rows are retained separately, including prior versions. Current report snapshots and historic event JSON are intentional distinct time facts; operational relationships remain relational.\n";
    file_put_contents($root.'data_dictionary'.$suffix.'.md',$dict);
    // Dynamic layout includes every actual table, unlike the old hard-coded inventory.
    $escape=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_XML1,'UTF-8');$lanes=array_fill(0,5,125);$positions=[];
    foreach($schema as $table=>$cols){$lane=array_search(min($lanes),$lanes,true);$h=56+count($cols)*20;$positions[$table]=['x'=>30+$lane*440,'y'=>$lanes[$lane],'h'=>$h];$lanes[$lane]+=$h+40;}
    $height=max($lanes);$svg='<svg xmlns="http://www.w3.org/2000/svg" width="2230" height="'.$height.'" viewBox="0 0 2230 '.$height.'"><title>BloodMatch '.$escape($name).' ERD</title><desc>'.$escape($status).'; all '.count($tables).' physical tables; composite relationship details are in the accompanying dictionary.</desc><rect width="100%" height="100%" fill="#f8fafc"/><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="none" stroke="#94a3b8"/></marker></defs><g font-family="Arial,sans-serif"><text x="30" y="34" font-size="22">BloodMatch - '.$escape($name).' - '.$escape($stamp).'</text><text x="30" y="61" font-size="15">'.$escape($status).'</text><text x="30" y="85" font-size="13">Arrows: child to parent. Full composite keys and cardinalities: accompanying Markdown ERD and dictionary.</text>';
    foreach($grouped as $parts){$f=$parts[0];$a=$positions[$f['TABLE_NAME']];$b=$positions[$f['REFERENCED_TABLE_NAME']];if($f['TABLE_NAME']===$f['REFERENCED_TABLE_NAME'])continue;$ax=$a['x']+405;$ay=$a['y']+24;$bx=$b['x'];$by=$b['y']+24;$mid=($ax+$bx)/2;$svg.='<path d="M'.$ax.','.$ay.' C'.$mid.','.$ay.' '.$mid.','.$by.' '.$bx.','.$by.'" fill="none" stroke="#cbd5e1" marker-end="url(#arrow)"><title>'.$escape($f['TABLE_NAME'].'.'.implode(',',array_column($parts,'COLUMN_NAME')).' - '.$f['REFERENCED_TABLE_NAME']).'</title></path>';}
    foreach($schema as $table=>$cols){$pos=$positions[$table];$archived=$new&&in_array($table,['donation_credits','donation_report_holds','compatibility_matrix'],true);$svg.='<g transform="translate('.$pos['x'].','.$pos['y'].')"><rect width="405" height="'.$pos['h'].'" rx="6" fill="'.($archived?'#fff7ed':'#fff').'" stroke="#94a3b8"/><text x="12" y="25" font-size="16" font-weight="bold">'.$escape($table).'</text>';foreach($cols as $i=>$c){$label=$c['COLUMN_NAME'].($c['IS_NULLABLE']==='YES'?' ?':'');$svg.='<text x="12" y="'.(50+$i*20).'" font-size="12">'.$escape($label).'<title>'.$escape($c['COLUMN_TYPE'].' '.$c['EXTRA']).'</title></text>';}$svg.='</g>';}$svg.='</g></svg>';file_put_contents($root.'erd'.$suffix.'.svg',$svg);
    echo 'Exported '.($test?'tested':'application').' metadata: '.count($tables).' tables; migration032='.($new?'recorded':'pending').'. No row contents exported.'.PHP_EOL;
}catch(Throwable $e){fwrite(STDERR,'Export stopped: '.$e->getMessage().PHP_EOL);exit(1);}
